<?php
require_once __DIR__.'/../includes/init.php';
require_role('owner');
require_once __DIR__.'/../includes/layout.php';
$pdo=db();
$from=(string)($_GET['from']??date('Y-m-01'));
$to=(string)($_GET['to']??date('Y-m-d'));
$q=trim((string)($_GET['q']??''));
$petugas=(int)($_GET['petugas']??0);
$error=''; $rows=[]; $summary=[]; $staffList=[]; $entryStaff=[]; $exitStaff=[]; $total=0; $revenue=0.0;
try {
    [$a,$b]=valid_date_range($from,$to);
    $staffList=$pdo->query("SELECT id_user_petugas_masuk AS id_user,nama_petugas_masuk AS nama FROM v_rekap_transaksi WHERE id_user_petugas_masuk IS NOT NULL UNION SELECT id_user_petugas_keluar AS id_user,nama_petugas_keluar AS nama FROM v_rekap_transaksi WHERE id_user_petugas_keluar IS NOT NULL ORDER BY nama")->fetchAll();
    $where=["status='keluar'",'waktu_keluar BETWEEN ? AND ?']; $params=[$a,$b];
    if ($q!=='') { $where[]="(CAST(id_parkir AS CHAR) LIKE ? OR plat_nomor LIKE ? OR COALESCE(nama_petugas_masuk,'') LIKE ? OR COALESCE(nama_petugas_keluar,'') LIKE ?)"; array_push($params,'%'.$q.'%','%'.$q.'%','%'.$q.'%','%'.$q.'%'); }
    if ($petugas>0) { $where[]='(id_user_petugas_masuk=? OR id_user_petugas_keluar=?)'; array_push($params,$petugas,$petugas); }
    $sqlWhere=implode(' AND ',$where);
    $s=$pdo->prepare("SELECT id_parkir,plat_nomor,jenis_kendaraan,waktu_masuk,waktu_keluar,durasi_jam,tarif_saat_masuk,biaya_total,status,nama_area,nama_petugas_masuk,id_user_petugas_masuk,nama_petugas_keluar,id_user_petugas_keluar,metode_pembayaran,status_pembayaran,waktu_bayar FROM v_rekap_transaksi WHERE $sqlWhere ORDER BY waktu_keluar DESC,id_parkir DESC");
    $s->execute($params); $rows=$s->fetchAll(); $total=count($rows);
    foreach ($rows as $r) {
        $revenue+=(float)$r['biaya_total'];
        $inId=(int)($r['id_user_petugas_masuk']??0); $inName=(string)($r['nama_petugas_masuk']??'Tidak diketahui');
        if ($inId>0) { if(!isset($entryStaff[$inId])) $entryStaff[$inId]=['id'=>$inId,'name'=>$inName,'count'=>0]; $entryStaff[$inId]['count']++; }
        $outId=(int)($r['id_user_petugas_keluar']??0); $outName=(string)($r['nama_petugas_keluar']??'Belum tercatat');
        if ($outId>0) { if(!isset($exitStaff[$outId])) $exitStaff[$outId]=['id'=>$outId,'name'=>$outName,'count'=>0,'revenue'=>0.0]; $exitStaff[$outId]['count']++; $exitStaff[$outId]['revenue']+=(float)$r['biaya_total']; }
        $kind=(string)$r['jenis_kendaraan']; if(!isset($summary[$kind]))$summary[$kind]=['count'=>0,'revenue'=>0.0]; $summary[$kind]['count']++; $summary[$kind]['revenue']+=(float)$r['biaya_total'];
    }
    uasort($entryStaff,static fn($x,$y)=>strcmp($x['name'],$y['name']));
    uasort($exitStaff,static fn($x,$y)=>strcmp($x['name'],$y['name']));

    if (($_GET['format']??'')==='csv') {
        $name='parkirstrd-laporan-owner-'.$from.'-'.$to.'.csv';
        header('Content-Type: text/csv; charset=utf-8'); header('Content-Disposition: attachment; filename="'.$name.'"');
        $out=fopen('php://output','w'); fwrite($out,"\xEF\xBB\xBF");
        $csvSafe=static function(mixed $v): mixed { if(!is_string($v))return $v; return preg_match('/^[=+\-@\t\r]/',$v)?"'".$v:$v; };
        fputcsv($out,['ParkirSTRD - Laporan transaksi selesai',$from.' sampai '.$to]);
        fputcsv($out,['Total transaksi',$total,'Total pendapatan',number_format($revenue,0,'.','')]);
        fputcsv($out,['ID Parkir','Plat Nomor','Jenis Kendaraan','Waktu Masuk','Waktu Keluar','Durasi Jam','Tarif Saat Masuk','Total Biaya','Area','Petugas Masuk','Petugas Keluar','Metode Pembayaran','Status Pembayaran','Waktu Bayar']);
        foreach($rows as $r) fputcsv($out,array_map($csvSafe,[$r['id_parkir'],$r['plat_nomor'],$r['jenis_kendaraan'],$r['waktu_masuk'],$r['waktu_keluar'],$r['durasi_jam'],$r['tarif_saat_masuk'],$r['biaya_total'],$r['nama_area'],$r['nama_petugas_masuk'],$r['nama_petugas_keluar'],$r['metode_pembayaran'],$r['status_pembayaran'],$r['waktu_bayar']]));
        fputcsv($out,[]); fputcsv($out,['Rekap Pendapatan Berdasarkan Petugas Keluar']); fputcsv($out,['ID Petugas','Nama Petugas','Jumlah Transaksi Keluar','Nilai Transaksi']);
        foreach($exitStaff as $r) fputcsv($out,[$r['id'],$csvSafe($r['name']),$r['count'],number_format($r['revenue'],0,'.','')]);
        fclose($out); exit;
    }
    if (($_GET['format']??'')==='print') {
        ?><!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Laporan ParkirSTRD</title><style>body{font:12px Arial,sans-serif;color:#222;margin:24px}h1,h2{margin:0 0 8px}p{margin:4px 0 16px;color:#555}.top{display:flex;justify-content:space-between;border-bottom:2px solid #7450bd;padding-bottom:12px;margin-bottom:18px}.actions{margin-bottom:16px}button{padding:8px 14px;border:0;background:#7450bd;color:white;border-radius:6px}table{width:100%;border-collapse:collapse;margin:10px 0 24px}th,td{border:1px solid #ddd;padding:6px;text-align:left}th{background:#f1ecfb}section{break-inside:avoid}.num{text-align:right}@media print{.actions{display:none}body{margin:8mm}.top{break-after:avoid}thead{display:table-header-group}tr{break-inside:avoid}}</style></head><body><div class="actions"><button onclick="window.print()">Cetak / Simpan sebagai PDF</button></div><header class="top"><div><h1>ParkirSTRD</h1><strong>Laporan transaksi parkir selesai</strong><p>Periode: <?= h($from) ?> sampai <?= h($to) ?></p></div><div>Dibuat: <?= h(date('d/m/Y H:i')) ?><br>Total transaksi: <?= $total ?><br>Total nominal transaksi: <?= h(rupiah($revenue)) ?></div></header><section><h2>Rincian transaksi</h2><table><thead><tr><th>ID</th><th>Plat</th><th>Jenis</th><th>Masuk</th><th>Keluar</th><th>Durasi</th><th>Petugas masuk</th><th>Petugas keluar</th><th>Pembayaran</th><th>Total</th></tr></thead><tbody><?php foreach($rows as $r): ?><tr><td>#<?= (int)$r['id_parkir'] ?></td><td><?= h($r['plat_nomor']) ?></td><td><?= h($r['jenis_kendaraan']) ?></td><td><?= h($r['waktu_masuk']) ?></td><td><?= h($r['waktu_keluar']) ?></td><td><?= (int)$r['durasi_jam'] ?> jam</td><td><?= h($r['nama_petugas_masuk']??'-') ?></td><td><?= h($r['nama_petugas_keluar']??'-') ?></td><td><?= h(($r['metode_pembayaran']??'-').' / '.($r['status_pembayaran']??'-')) ?></td><td><?= h(rupiah($r['biaya_total'])) ?></td></tr><?php endforeach; if(!$rows): ?><tr><td colspan="10">Tidak ada transaksi untuk filter ini.</td></tr><?php endif; ?></tbody></table></section><section><h2>Pendapatan berdasarkan petugas keluar</h2><p>Nilai transaksi dialokasikan ke petugas yang memproses kendaraan keluar agar total pendapatan tidak terhitung dua kali.</p><table><thead><tr><th>ID Petugas</th><th>Nama</th><th>Jumlah transaksi</th><th>Nilai transaksi</th></tr></thead><tbody><?php foreach($exitStaff as $r): ?><tr><td><?= (int)$r['id'] ?></td><td><?= h($r['name']) ?></td><td><?= (int)$r['count'] ?></td><td><?= h(rupiah($r['revenue'])) ?></td></tr><?php endforeach; if(!$exitStaff): ?><tr><td colspan="4">Belum ada data.</td></tr><?php endif; ?></tbody></table></section><section><h2>Aktivitas kendaraan masuk berdasarkan petugas</h2><table><thead><tr><th>ID Petugas</th><th>Nama</th><th>Transaksi masuk yang dicatat</th></tr></thead><tbody><?php foreach($entryStaff as $r): ?><tr><td><?= (int)$r['id'] ?></td><td><?= h($r['name']) ?></td><td><?= (int)$r['count'] ?></td></tr><?php endforeach; if(!$entryStaff): ?><tr><td colspan="3">Belum ada data.</td></tr><?php endif; ?></tbody></table></section><script>window.addEventListener('load',()=>{setTimeout(()=>window.print(),250)});</script></body></html><?php
        exit;
    }
} catch(Throwable $e) {
    if ($e instanceof InvalidArgumentException) $error=$e->getMessage();
    else { error_log('[ParkirSTRD owner report] '.$e->getMessage()); $error='Laporan belum dapat diproses. Pastikan migrasi ParkirSTRD sudah diimpor.'; }
}
render_header('Laporan Owner','laporan');
?>
<div class="page-intro"><div><h2>Laporan transaksi dan pendapatan</h2><p>Owner memiliki akses baca saja. Pendapatan diatribusikan kepada petugas yang memproses kendaraan keluar agar tidak dihitung ganda.</p></div><div class="table-actions"><a class="btn btn-secondary" target="_blank" rel="noopener" href="<?= h(url('owner/laporan.php?'.http_build_query(array_merge($_GET,['format'=>'print'])))) ?>">Cetak / Simpan PDF</a><?php if(!$error): ?><a class="btn btn-primary" href="<?= h(url('owner/laporan.php?'.http_build_query(array_merge($_GET,['format'=>'csv'])))) ?>">Ekspor Excel-compatible CSV</a><?php endif; ?></div></div>
<?php if($error): ?><div class="alert alert-error"><?= h($error) ?></div><?php endif; ?>
<section class="panel"><form method="get" class="filter-row"><div class="field"><label>Tanggal mulai (keluar)</label><input type="date" name="from" value="<?= h($from) ?>" required></div><div class="field"><label>Tanggal akhir</label><input type="date" name="to" value="<?= h($to) ?>" required></div><div class="field" style="min-width:210px"><label>Petugas terlibat</label><select name="petugas"><option value="0">Semua petugas</option><?php foreach($staffList as $staff): ?><option value="<?= (int)$staff['id_user'] ?>" <?= $petugas===(int)$staff['id_user']?'selected':'' ?>><?= h($staff['nama']) ?> (#<?= (int)$staff['id_user'] ?>)</option><?php endforeach; ?></select></div><div class="field" style="min-width:200px"><label>Pencarian</label><input type="search" name="q" value="<?= h($q) ?>" placeholder="Plat, ID, nama petugas"></div><button class="btn btn-primary">Terapkan filter</button><a class="btn btn-secondary" href="<?= h(url('owner/laporan.php')) ?>">Reset</a></form></section>
<div class="stats-grid"><article class="stat-card"><div class="stat-top"><span class="stat-label">Total nominal transaksi</span><span class="stat-icon green">Rp</span></div><div class="stat-value" style="font-size:21px"><?= h(rupiah($revenue)) ?></div><div class="stat-foot">Transaksi selesai dalam filter</div></article><article class="stat-card"><div class="stat-top"><span class="stat-label">Jumlah transaksi</span><span class="stat-icon">⇄</span></div><div class="stat-value"><?= number_format($total) ?></div><div class="stat-foot">Periode laporan</div></article><article class="stat-card"><div class="stat-top"><span class="stat-label">Rata-rata nominal</span><span class="stat-icon cyan">∅</span></div><div class="stat-value" style="font-size:21px"><?= h(rupiah($total?$revenue/$total:0)) ?></div><div class="stat-foot">Nominal / transaksi</div></article><article class="stat-card"><div class="stat-top"><span class="stat-label">Petugas keluar</span><span class="stat-icon orange">♙</span></div><div class="stat-value"><?= count($exitStaff) ?></div><div class="stat-foot">Petugas dengan transaksi selesai</div></article></div>
<section class="panel"><div class="panel-heading"><div><h2>Rincian transaksi selesai</h2><p>Data mengikuti filter tanggal, petugas, dan kata kunci.</p></div></div><div class="table-wrap"><table><thead><tr><th>ID</th><th>Plat</th><th>Jenis</th><th>Waktu masuk</th><th>Waktu keluar</th><th>Durasi</th><th>Petugas masuk</th><th>Petugas keluar</th><th>Metode / status</th><th>Total</th></tr></thead><tbody><?php foreach(array_slice($rows,0,200) as $r): ?><tr><td class="td-main">#<?= (int)$r['id_parkir'] ?></td><td><?= h($r['plat_nomor']) ?></td><td><?= h(ucfirst($r['jenis_kendaraan'])) ?></td><td><?= h(tanggal($r['waktu_masuk'])) ?></td><td><?= h(tanggal($r['waktu_keluar'])) ?></td><td><?= (int)$r['durasi_jam'] ?> jam</td><td><?= h($r['nama_petugas_masuk']??'-') ?></td><td><?= h($r['nama_petugas_keluar']??'-') ?></td><td><?= h(($r['metode_pembayaran']??'-').' / '.($r['status_pembayaran']??'-')) ?></td><td class="td-main"><?= h(rupiah($r['biaya_total'])) ?></td></tr><?php endforeach; if(!$rows): ?><tr><td colspan="10"><div class="empty-state">Tidak ada transaksi selesai sesuai filter.</div></td></tr><?php endif; ?></tbody></table></div><div class="table-foot"><span>Menampilkan maksimal 200 baris pada layar; ekspor CSV memuat semua hasil sesuai filter.</span></div></section>
<div class="content-grid"><section class="panel"><div class="panel-heading"><div><h2>Aktivitas kendaraan masuk</h2><p>Dihitung dari petugas yang merekam kendaraan masuk.</p></div></div><div class="table-wrap"><table><thead><tr><th>Petugas</th><th>Transaksi masuk</th></tr></thead><tbody><?php foreach($entryStaff as $r): ?><tr><td><?= h($r['name']) ?> <span class="muted">#<?= (int)$r['id'] ?></span></td><td><?= (int)$r['count'] ?></td></tr><?php endforeach; if(!$entryStaff): ?><tr><td colspan="2">Belum ada data.</td></tr><?php endif; ?></tbody></table></div></section><section class="panel"><div class="panel-heading"><div><h2>Pendapatan berdasarkan petugas keluar</h2><p>Setiap transaksi hanya dialokasikan sekali ke petugas keluar.</p></div></div><div class="table-wrap"><table><thead><tr><th>Petugas</th><th>Transaksi keluar</th><th>Nilai transaksi</th></tr></thead><tbody><?php foreach($exitStaff as $r): ?><tr><td><?= h($r['name']) ?> <span class="muted">#<?= (int)$r['id'] ?></span></td><td><?= (int)$r['count'] ?></td><td class="td-main"><?= h(rupiah($r['revenue'])) ?></td></tr><?php endforeach; if(!$exitStaff): ?><tr><td colspan="3">Belum ada data.</td></tr><?php endif; ?></tbody></table></div></section></div>
<?php render_footer(); ?>
